"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { Switch } from "@/components/ui/switch";
import { DataGridBody, DataGridHeader, DataGridProvider, DataGridRoot, defineColumns } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridServerRows } from "@/registry/default/components/data-grid-server/data-grid-server";
import { describeFilterOperators, withColumnMap } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import { DataGridHeaderFilter } from "@/registry/default/components/data-grid-toolbar/data-grid-toolbar";
import type { LoggedQuery, QueryDemoRow } from "./data-grid-server-query-demo-db";

const columnDefs = defineColumns<QueryDemoRow>()([
  { id: "id", header: "Id", accessorKey: "id", type: "number", width: 70 },
  { id: "soldOn", header: "Sold on", accessorKey: "soldOn", type: "date", width: 110 },
  { id: "customer", header: "Customer", accessorKey: "customer", type: "text", width: 140, flex: 1 },
  { id: "region", header: "Region", accessorKey: "region", type: "select", width: 90 },
  { id: "dealership", header: "Dealership", accessorKey: "dealership", type: "select", width: 160 },
  { id: "salesperson", header: "Salesperson", accessorKey: "salesperson", type: "text", width: 130 },
  { id: "make", header: "Make", accessorKey: "make", type: "select", width: 90 },
  { id: "model", header: "Model", accessorKey: "model", type: "text", width: 90 },
  { id: "price", header: "Price", accessorKey: "price", type: "number", width: 90 },
  { id: "discount", header: "Discount", accessorKey: "discount", type: "number", width: 90 },
  { id: "financed", header: "Financed", accessorKey: "financed", type: "checkbox", width: 90 },
] as const);

const HOSTILE_FILTER = { filterId: "hostile", columnId: "customer", operator: "contains", value: "'; DROP TABLE car_sales; --" };

type Demo = Awaited<ReturnType<typeof import("./data-grid-server-query-demo-db").createQueryDemo>>;

const loadDemo = (onQuery: (entry: LoggedQuery) => void) => import("./data-grid-server-query-demo-db").then(({ createQueryDemo }) => createQueryDemo(onQuery));

/**
 * A grid over an in-browser PostgreSQL. Each request goes through `fetchRows` of the query layer, which reads the column map and runs
 * Drizzle. The panel shows the statement and the bound parameters of the last request. The switch adds a hostile filter value to every request.
 */
export default function DataGridServerQueryDemo(): ReactNode {
  const [demo, setDemo] = useState<Demo | null>(null);
  const [last, setLast] = useState<LoggedQuery[]>([]);
  const logRef = useRef<LoggedQuery[]>([]);

  useEffect(() => {
    let cancelled = false;
    void loadDemo((entry) => {
      logRef.current = [...logRef.current.slice(-1), entry];
      setLast(logRef.current);
    }).then((ready) => {
      if (!cancelled) setDemo(ready);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  if (!demo) {
    return <div className="flex h-[420px] w-full items-center justify-center rounded-md border border-border text-sm text-muted-foreground">Starting the in-browser database…</div>;
  }
  return <QueryGrid demo={demo} last={last} />;
}

function QueryGrid({ demo, last }: { demo: Demo; last: LoggedQuery[] }): ReactNode {
  const [hostile, setHostile] = useState(false);
  return (
    <div className="flex w-full flex-col gap-2">
      <label className="flex items-center gap-2 text-sm text-muted-foreground">
        <Switch checked={hostile} onCheckedChange={setHostile} />
        Add a hostile filter value
      </label>
      <HostileGrid key={String(hostile)} demo={demo} last={last} hostile={hostile} />
    </div>
  );
}

function HostileGrid({ demo, last, hostile }: { demo: Demo; last: LoggedQuery[]; hostile: boolean }): ReactNode {
  const columns = useMemo(() => withColumnMap(columnDefs, describeFilterOperators(demo.columns)), [demo.columns]);

  const server = useDataGridServerRows<QueryDemoRow>({
    mode: "scroll",
    getRowId: (row) => String(row.id),
    blockSize: 50,
    fetchRows: ({ signal, spec, ...request }) => {
      const filters = hostile ? [...spec.filters, HOSTILE_FILTER] : spec.filters;
      return demo.query.fetchRows({ ...request, spec: { ...spec, filters } }, { signal });
    },
  });

  return (
    <div className="flex w-full flex-col gap-2">
      <p className="text-sm text-muted-foreground">
        {(server.totalRowCount ?? demo.total).toLocaleString("en-US")} rows match<span className={server.loading ? undefined : "invisible"}> · fetching…</span>
      </p>
      <div className="flex h-[360px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider
          {...server.providerProps}
          columns={columns}
          fetchFilterValues={({ columnId, query, filters }) => demo.query.filterValues({ columnId, query, filters })}
          readOnly
        >
          <DataGridRoot className="min-h-0 flex-1 rounded-[inherit] border-none" renderHeaderFilter={(ctx) => <DataGridHeaderFilter {...ctx} />} {...server.rootProps}>
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
      <div className="rounded-md border border-border bg-muted/40 p-3 text-xs">
        <p className="mb-1 font-medium text-foreground">Last statements</p>
        {last.length === 0 ? <p className="text-muted-foreground">None yet.</p> : null}
        {last.map((entry, index) => (
          <div key={index} className="mb-2 last:mb-0">
            <pre className="whitespace-pre-wrap break-all font-mono text-foreground">{entry.sql}</pre>
            <pre className="whitespace-pre-wrap break-all font-mono text-muted-foreground">params: {JSON.stringify(entry.params)}</pre>
          </div>
        ))}
      </div>
    </div>
  );
}

import { PGlite } from "@electric-sql/pglite";
import { boolean, date, integer, pgTable, text } from "drizzle-orm/pg-core";
import { drizzle } from "drizzle-orm/pglite";
import { columnsFromDrizzleTable, createDrizzleGridQuery } from "@/registry/default/components/data-grid-server-query-drizzle/data-grid-server-query-drizzle";

/** One car sold by a dealership. */
export type QueryDemoRow = {
  id: number;
  soldOn: string;
  region: string;
  dealership: string;
  salesperson: string;
  make: string;
  model: string;
  customer: string;
  price: number;
  discount: number;
  financed: boolean;
};
export type LoggedQuery = { sql: string; params: unknown[] };

const carSales = pgTable("car_sales", {
  id: integer("id").primaryKey(),
  soldOn: date("sold_on", { mode: "string" }).notNull(),
  region: text("region").notNull(),
  dealership: text("dealership").notNull(),
  salesperson: text("salesperson").notNull(),
  make: text("make").notNull(),
  model: text("model").notNull(),
  customer: text("customer").notNull(),
  price: integer("price").notNull(),
  discount: integer("discount").notNull(),
  financed: boolean("financed").notNull(),
});

const REGIONS = ["North", "South", "East", "West"];
const DEALERSHIPS = ["Northgate Motors", "Pine Ridge Cars", "Bayview Autos", "Southfield Motors", "Eastbrook Cars", "Harbor Point Motors", "Westlake Autos", "Canyon Road Motors"];
const SALESPEOPLE = ["Dana Brooks", "Eli Moreno", "Fern Walsh", "Gus Ortega", "Hana Ito", "Ivan Petrov", "Jade Lin", "Kofi Mensah", "Lena Fischer", "Milo Grant", "Nia Duarte", "Omar Aziz", "Pia Lund", "Raul Vega", "Sana Mir", "Theo Clark"];
const MAKES = ["Kestrel", "Marlow", "Nordvik", "Solenne", "Vantor"];
const MODELS = [["Brook", "Glide", "Summit"], ["Coast", "Harbor", "Tide"], ["Birch", "Fjord", "Frost"], ["Dawn", "Lumen", "Opal"], ["Ember", "Flint", "Quarry"]];
// Unequal shares per region and a different make mix in each region, so the pivot and the group totals differ.
const REGION_SLOTS = [0, 0, 0, 0, 1, 1, 1, 2, 2, 3];
const MAKE_MIX = [
  [0, 0, 0, 1, 2, 3, 4, 1],
  [1, 1, 1, 2, 0, 3, 4, 2],
  [2, 2, 3, 3, 3, 0, 1, 4],
  [4, 4, 4, 3, 0, 1, 2, 4],
];
const FIRST = ["Alex", "Sam", "Jordan", "Taylor", "Morgan", "Casey", "Riley", "Jamie", "Avery", "Quinn", "Drew", "Robin"];
const LAST = ["Smith", "Garcia", "Chen", "Patel", "Novak", "Okafor", "Larsen", "Rossi", "Kim", "Silva", "Meyer", "Haddad"];
const ROW_COUNT = 5000;

/** Opens an in-browser PostgreSQL, seeds it with 5,000 fictional car sales, and wires the query layer to it. Every statement the layer runs goes to `onQuery`. */
export async function createQueryDemo(onQuery: (entry: LoggedQuery) => void) {
  const pg = new PGlite();
  await pg.exec(
    "create table car_sales (id integer primary key, sold_on date not null, region text not null, dealership text not null, salesperson text not null, make text not null, model text not null, customer text not null, price integer not null, discount integer not null, financed boolean not null)",
  );
  // The seed names hold no quote, so plain interpolation stays valid SQL.
  const values = Array.from({ length: ROW_COUNT }, (_, index) => {
    const region = REGION_SLOTS[index % REGION_SLOTS.length]!;
    const mix = MAKE_MIX[region]!;
    const make = mix[Math.floor(index / REGION_SLOTS.length) % mix.length]!;
    const model = Math.floor(index / 80) % 3;
    const dealership = region * 2 + (Math.floor(index / 7) % 3 === 0 ? 1 : 0);
    const salesperson = SALESPEOPLE[dealership * 2 + (Math.floor(index / 13) % 2)]!;
    const customer = `${FIRST[Math.floor(index / 5) % FIRST.length]!} ${LAST[(index * 7) % LAST.length]!}`;
    const soldOn = new Date(Date.UTC(2025, 0, 1 + ((index * 7) % 365))).toISOString().slice(0, 10);
    const price = 21000 + make * 6000 + model * 9000 + ((index * 37) % 41) * 100;
    const discount = ((index * 7) % 13) * 250;
    return `(${index + 1}, '${soldOn}', '${REGIONS[region]!}', '${DEALERSHIPS[dealership]!}', '${salesperson}', '${MAKES[make]!}', '${MODELS[make]![model]!}', '${customer}', ${price}, ${discount}, ${index % 3 !== 0})`;
  });
  await pg.exec(`insert into car_sales values ${values.join(", ")}`);
  const db = drizzle(pg, { logger: { logQuery: (sql, params) => onQuery({ sql, params }) } });
  const columns = columnsFromDrizzleTable(carSales, {
    pick: ["id", "soldOn", "region", "dealership", "salesperson", "make", "model", "customer", "price", "discount", "financed"],
    overrides: {
      customer: { searchable: true },
      salesperson: { searchable: true },
      model: { searchable: true },
      region: { type: "select", choices: REGIONS },
      dealership: { type: "select", choices: DEALERSHIPS },
      make: { type: "select", choices: MAKES },
      price: { aggregate: "sum" },
    },
  });
  const query = createDrizzleGridQuery<QueryDemoRow>({ db, table: carSales, columns });
  return { query, columns, total: ROW_COUNT };
}
